/* Render reviewed, aggregate-only waiting data. No patient input or storage. */
(()=>{'use strict';const page=document.querySelector('[data-allocation-page]');if(!page)return;
 let dataset=null,initAttempts=0;const disease=document.getElementById('allocation-disease'),cohort=document.getElementById('waiting-cohort'),results=document.getElementById('waiting-results');
 const pct=x=>(x*100).toFixed(1)+'%',ci=(p,k)=>`${pct(p[k+'_low'])}–${pct(p[k+'_high'])}`,e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function chart(c){
