 },
 "sets": {
  "roadmap": {
   "label": "Roadmap",
   "page": "incidental/",
   "web": "incidental/#questions",
   "questions": [
    {
     "id": "INC-D1",
     "set": "roadmap",
     "title": "Which incidental liver lesions may be discharged by the radiologist at the index report without any clinical referral, and which must be referred?",
     "question": "Which incidental liver lesions may be discharged by the radiologist at the index report without any clinical referral, and which must be referred?",
     "kind": "clinical",
     "status": "OPEN — not yet decided",
     "where": [
      {
       "label": "2 · Characterize a cystic lesion",
       "url": "incidental/#decision-2"
      },
      {
       "label": "3 · Select the next imaging test",
       "url": "incidental/#decision-3"
      },
      {
       "label": "4 · Hemangioma or focal nodular hyperplasia",
       "url": "incidental/#decision-4"
      },
      {
       "label": "5 · Pseudolesions and benign liver nodules",
       "url": "incidental/#decision-5"
      },
      {
       "label": "6 · Indeterminate liver lesion",
       "url": "incidental/#decision-6"
      }
     ],
     "positions": [
      {
       "source": "ACR liver white paper 2017",
       "key": "pm28927870",
       "says": "Forgo workup of lesions under 1 cm in low-risk patients and of lesions with distinctly benign features at any risk; the committee itself says this is guidance, not standard of care, meeting no formal national standard.",
       "locator": "Clinical decision 2 · Avoid 'Do not give a simple cyst a surveillance interval.'; What we are not sure about #15"
      },
      {
       "source": "EASL benign tumours 2016",
       "key": "pm27085809",
       "says": "A typical haemangioma and a typical FNH need no imaging follow-up, FNH unless there is underlying vascular liver disease; the ultrasound-only haemangioma diagnosis does not extend to oncology or liver-disease patients.",
       "locator": "Clinical decision 4 · Standard 'In a normal liver, a hyperechoic lesion under 3 cm…' and 'Focal nodular hyperplasia can be diagnosed with nearly 100% specificity…'"
      },
      {
       "source": "ACR abdominal CT white paper 2010",
       "key": "pm20889105",
       "says": "The predecessor set the small-lesion stratum at 0.5 cm and the interval at 6 months; the roadmap notes these thresholds changed by 2017 with no new evidence cited.",
       "locator": "Clinical decision 6 · Standard 'A new sub-centimetre lesion in a patient with cancer…' (caveat); What we are not sure about #15"
      }
     ],
     "divergence": "The radiology consensus defines which lesions need no workup but not who owns the discharge, and its thresholds are conventions that changed between editions without new evidence.",
     "proposal": "Discharge rules cover the simple cyst, biliary hamartomas, typical haemangioma, typical FNH outside vascular liver disease, characteristic focal fat or perfusion change, and a sub-centimetre lesion in a low-risk patient, each on an adequate index study with a written discharge naming the entity. Triage assumes many are resolved by the radiologist; who owns the discharge is not stated.",
     "proposal_locator": "Clinical decisions 2, 4 and 5 (Standard discharge rules); Clinical decision 6 · Standard 'A new sub-centimetre lesion…'; Clinical decision 8 · Avoid 'Do not discharge a patient from this page without telling them, in writing…'; The board meeting · Triage",
     "rationale": "The ACR algorithm is explicit that lesions under 1 cm in low-risk patients and lesions with distinctly benign features in any patient need no workup, but it is a radiology consensus document and it does not say who owns the discharge. Without a local rule, either every finding generates a referral or none does.",
     "audit": "Proportion discharged at the index report; follow-up intervals recommended for lesions meeting benign-feature criteria.",
     "web": "incidental/#question-INC-D1"
    },
    {
     "id": "INC-D2",
     "set": "roadmap",
     "title": "How is the at-risk question answered and recorded when cirrhosis is suspected but not established?",
     "question": "How is the at-risk question answered and recorded when cirrhosis is suspected but not established?",
     "kind": "clinical",
     "status": "OPEN — not yet decided",
     "where": [
      {
       "label": "0 · Assess background liver disease",
       "url": "incidental/#decision-0"
      }
     ],
     "positions": [
      {
       "source": "LI-RADS v2018",
       "key": "pm30251931",
       "says": "Defines the at-risk population as cirrhosis, chronic hepatitis B, or current or prior HCC (adult transplant candidates included); cirrhosis from vascular disorders and congenital hepatic fibrosis are excluded.",
       "locator": "Clinical decision 0 · Standard 'Answer the at-risk question first…'; Quick reference · 'Who the at-risk algorithms apply to'"
      },
      {
       "source": "EASL HCC 2025",
       "key": "pm39690085",
       "says": "Non-invasive criteria apply only with cirrhosis, chronic HBV or prior HCC; others need biopsy to diagnose HCC (LoE 1, strong), because pre-test probability outside those groups is not precisely established.",
       "locator": "Clinical decision 0 · Standard 'In a liver that is not at risk, accept that no imaging criterion set exists…'"
      },
      {
       "source": "AASLD HCC 2023",
       "key": "pm37199193",
       "says": "Builds its diagnostic algorithm on the same at-risk population and uses the LI-RADS lexicon.",
       "locator": "Clinical decision 0 · Standard 'Answer the at-risk question first…'"
      }
     ],
     "divergence": "The guidelines agree on who is at risk, but none defines what to do with the intermediate patient whose cirrhosis is suspected but not established.",
     "proposal": "When cirrhosis is suspected but unproven, state that uncertainty explicitly and treat the pathway as undetermined rather than defaulting to the at-risk arm; obtain a hepatology opinion and decide the pathway once (Reasonable, grade D). Record the aetiology and how cirrhosis was or was not established.",
     "proposal_locator": "Clinical decision 0 · Reasonable 'Where cirrhosis is suspected but not established…'; Clinical decision 0 · Standard 'Answer the at-risk question first…' (note); What we are not sure about #2",
     "rationale": "The whole algorithm forks here, and neither LI-RADS nor EASL 2025 defines the intermediate patient. EASL states only that pre-test probability in non-cirrhotic populations has not been precisely established.",
     "audit": "Cases in which the at-risk determination was changed after the index report, and the reason.",
     "web": "incidental/#question-INC-D2"
    },
    {
     "id": "INC-D3",
     "set": "roadmap",
     "title": "Which MRI contrast agent is the default when the question has not been narrowed?",
     "question": "Which MRI contrast agent is the default when the question has not been narrowed?",
     "kind": "clinical",
     "status": "OPEN — not yet decided",
     "where": [
      {
       "label": "3 · Select the next imaging test",
       "url": "incidental/#decision-3"
      },
      {
       "label": "4 · Hemangioma or focal nodular hyperplasia",
       "url": "incidental/#decision-4"
      }
     ],
     "positions": [
      {
       "source": "EASL HCC 2025",
       "key": "pm39690085",
       "says": "Favour extracellular agents over gadoxetic acid for non-invasive HCC diagnosis (LoE 1, strong); hepatobiliary-phase hypointensity is only an ancillary finding, and the agent risks arterial-phase motion artefact.",
       "locator": "Clinical decision 3 · Reasonable options 'MRI with an extracellular gadolinium agent' and 'MRI with gadoxetate disodium'"
      },
      {
       "source": "ACR liver white paper 2017",
       "key": "pm28927870",
       "says": "Recommends gadoxetate specifically to separate FNH from adenoma, especially above 3 cm and subcapsular (4 cm in 2010, unexplained), while generally preferring gadolinium blood-pool agents.",
       "locator": "Clinical decision 3 · Reasonable options 'MRI with an extracellular gadolinium agent' and 'MRI with gadoxetate disodium'"
      },
      {
       "source": "HBP adenoma subtypes meta-analysis",
       "key": "pm35920706",
       "says": "Hepatobiliary-phase uptake occurs in 59% of beta-catenin-activated adenomas; specificity against all adenomas is 89%, the 65% figure applying only to the residual population; few lesions, case-control designs.",
       "locator": "Clinical decision 3 · Reasonable option 'MRI with gadoxetate disodium'; What we are not sure about #6"
      },
      {
       "source": "LI-RADS features IPD meta-analysis",
       "key": "pm34783596",
       "says": "Only one contributing study compared extracellular and hepatobiliary agents within the same observations, so no comparative estimate exists.",
       "locator": "Clinical decision 3 · Reasonable option 'MRI with an extracellular gadolinium agent' (note)"
      },
      {
       "source": "CRLM imaging meta-analysis",
       "key": "pm20829538",
       "says": "Liver-specific contrast gave no measurable benefit for detecting colorectal metastases.",
       "locator": "Clinical decision 1 · Standard 'Characterise with MRI, including diffusion-weighted imaging…' (caveat)"
      }
     ],
     "divergence": "EASL and the ACR white paper ask for different agents for different questions, which one acquisition cannot satisfy, and no source compares the agents head to head.",
