{
 "key": "pcyst",
 "code": "PCYST",
 "name": "Pancreatic cysts",
 "generated": "1 November 2026",
 "files": {
  "roadmap_info": "PCYST_1_Roadmap.docx",
  "roadmap_questions": "PCYST_2_Roadmap_Questions.docx",
  "decision": "PCYST_7_Decision_Discussion.docx"
 },
 "sets": {
  "roadmap": {
   "label": "Roadmap",
   "page": "pcyst/",
   "web": "pcyst/#questions",
   "questions": [
    {
     "id": "PCYST-D1",
     "set": "roadmap",
     "title": "Which guideline is this programme's spine — Kyoto 2024, ACG 2018, the European 2018 guideline, or AGA 2015?",
     "question": "Which guideline is this programme's spine — Kyoto 2024, ACG 2018, the European 2018 guideline, or AGA 2015?",
     "kind": "governance",
     "status": "OPEN — not yet decided",
     "where": [],
     "positions": [
      {
       "source": "NCCN Pancreatic Adenocarcinoma v1.2026",
       "key": "np-pcyst-nccn",
       "says": "Offers no cyst algorithm of its own; summarises the international and European groups, names Kyoto 2024 the international standard, cites the superseded 2013 European statement, and tells readers to use the most recent available guideline.",
       "locator": "Quick reference 'Resection thresholds compared, and the non-IPMN cysts' · row 'NCCN v1.2026'; Provenance"
      },
      {
       "source": "Kyoto 2024",
       "key": "pm38182527",
       "says": "The most recent guideline and the only one built on systematic reviews commissioned question by question; its own authors concede most IPMN studies lack high-level evidence, and it covers IPMN only, with no intervals for other cysts.",
       "locator": "Practice choices with limited evidence · item 1; Gate 8 · Standard option 'Kyoto 2024 schedule'"
      },
      {
       "source": "ACG 2018",
       "key": "pm29485131",
       "says": "The size-stratified schedule most US radiologists recognise, with MRCP preferred; graded conditional on very low quality evidence by ACG itself, which also says there are very few data on extending intervals and none on stopping by age.",
       "locator": "Gate 8 · Standard option 'ACG 2018 schedule'"
      },
      {
       "source": "European 2018",
       "key": "pm29574408",
       "says": "The simplest schedule to run and audit, since it does not branch on size, and the only one that also covers non-IPMN cysts; but the most imaging-intensive for a small stable cyst, with no demonstrated outcome advantage.",
       "locator": "Gate 8 · Standard option 'European 2018 schedule'"
      },
      {
       "source": "AGA 2015",
       "key": "pm25805375",
       "says": "The least intensive schedule and the only one with an explicit endpoint, but every recommendation is conditional on very low quality evidence and the AGA says its own surveillance interval has no evidence behind it.",
       "locator": "Gate 8 · Standard option 'AGA 2015 schedule'; Practice choices with limited evidence · item 28"
      }
     ],
     "divergence": "The four guidelines disagree on intervals, resection thresholds and stopping, NCCN declines to choose among them, and no study compares management under any of them on any outcome.",
     "proposal": "The roadmap uses Kyoto 2024 as its provisional spine (most recent, built on commissioned systematic reviews, cited by NCCN) while stating this is a choice, not demonstrated superiority. It takes non-IPMN management from the European guideline and ACG, and shows what the other three guidelines would do instead.",
     "proposal_locator": "Practice choices with limited evidence · item 1; Gate 5 · Reasonable 'Where the entity cannot be settled on imaging…' note; Provenance",
     "rationale": "NCCN takes no position and tells the reader to use the most recent available cyst guideline. The four differ on intervals, on resection thresholds and on stopping, and no study compares them. Until one is named, the same patient is managed differently depending on who sees them.",
     "audit": "Guideline and version recorded on every board output; proportion of cases managed off the named schedule.",
     "web": "pcyst/#question-PCYST-D1"
    },
    {
     "id": "PCYST-D2",
     "set": "roadmap",
     "title": "Which surveillance interval schedule, stated by size band, and which modality?",
     "question": "Which surveillance interval schedule, stated by size band, and which modality?",
     "kind": "clinical",
     "status": "OPEN — not yet decided",
     "where": [
      {
       "label": "8 · Surveillance without resection",
       "url": "pcyst/#decision-8"
      }
     ],
     "positions": [
      {
       "source": "Kyoto 2024",
       "key": "pm38182527",
       "says": "Under 20 mm: 6 months, then 18-monthly if stable; 20 to under 30 mm: 6 months twice, then yearly; 30 mm or more: 6-monthly; CT or MRI. Alone in having progression data under its bands, but IPMN only.",
       "locator": "Gate 8 · Standard option 'Kyoto 2024 schedule'"
      },
      {
       "source": "ACG 2018",
       "key": "pm29485131",
       "says": "Escalates with size, from MRI every 2 years under 1 cm to MRI alternating with EUS 6-monthly over 3 cm, with lengthening once stability is shown; MRCP preferred. Conditional recommendation on very low quality evidence.",
       "locator": "Gate 8 · Standard option 'ACG 2018 schedule'; Gate 8 · Standard 'Use MRI with MRCP…'"
      },
      {
       "source": "European 2018",
       "key": "pm29574408",
       "says": "MRI preferred; 6-monthly in the first year, then yearly for life while fit for surgery, regardless of size and for MCN under 40 mm alike; 6-monthly for relative indications, elderly and comorbid patients. Most imaging-intensive for small stable cysts.",
       "locator": "Gate 8 · Standard option 'European 2018 schedule'"
      },
      {
       "source": "AGA 2015",
       "key": "pm25805375",
       "says": "For cysts under 3 cm without a solid component or dilated duct: MRI at 1 year, then every 2 years, stopping at 5 years. The AGA says the interval is not based on evidence.",
       "locator": "Gate 8 · Standard option 'AGA 2015 schedule'"
      }
     ],
     "divergence": "The schedules differ threefold or more in imaging per patient-decade for the same cyst, have never been compared on any outcome, and three of the four concede their intervals lack an evidence base.",
     "proposal": "Choose one schedule, adopt it whole without mixing intervals and stopping rules from different guidelines, and record its name and version. The page's spine is the Kyoto 2024 schedule, with non-IPMN intervals still to be borrowed. Image with MRI and MRCP wherever available, CT only where MRI is unsuitable, keeping one modality throughout.",
     "proposal_locator": "Gate 8 · Standard options local approval note and option 'Kyoto 2024 schedule'; Gate 8 · Standard 'Use MRI with MRCP…'; Gate 8 · Avoid 'Do not mix the four schedules…'; Gate 1 · Reasonable 'Pancreas-protocol CT is an acceptable substitute…'",
     "rationale": "The four schedules differ by a factor of three or more in imaging per patient-decade for the same cyst, and three of the four state in their own texts that their intervals are not evidence-based. A schedule assembled case by case cannot be audited and cannot generate a growth rate. The ACG 2 to 3 cm band is now resolved from the full text — MRI or EUS every 6 to 12 months for 3 years, then yearly for 4 — so the remaining question is which guideline, not which reading of a figure.",
     "audit": "Schedule assigned at enrolment; adherence to interval; proportion of scans on the assigned modality.",
     "web": "pcyst/#question-PCYST-D2"
    },
    {
     "id": "PCYST-D3",
     "set": "roadmap",
     "title": "The stopping rule: continue while fit, stop at 5 years of stability, or stop by age and size?",
     "question": "The stopping rule: continue while fit, stop at 5 years of stability, or stop by age and size?",
     "kind": "clinical",
     "status": "OPEN — not yet decided",
     "where": [
      {
       "label": "9 · Consider stopping surveillance",
       "url": "pcyst/#decision-9"
      }
     ],
     "positions": [
      {
       "source": "European 2018",
       "key": "pm29574408",
       "says": "Follows patients without a surgical indication until they are no longer fit for surgery (GRADE 1B), reasoning that the risk of IPMN progression rises over time.",
       "locator": "Gate 9 · Standard option 'Continue while the patient remains fit — European 2018 and ACG 2018'"
      },
      {
       "source": "ACG 2018",
       "key": "pm29485131",
       "says": "Stops only on loss of surgical candidacy, reassesses utility over 75 and individualises at 76 to 85 (age limits it admits are borrowed and unsupported), and rejects the AGA 5-year rule, citing a 15 to 20-year dwell time.",
       "locator": "Gate 9 · Standard option 'Continue while the patient remains fit…'; Gate 9 · Standard 'Stop when the patient is no longer a candidate…'"
      },
      {
       "source": "AGA 2015",
       "key": "pm25805375",
       "says": "Stop after 5 years without significant change (conditional, very low quality); not restricted by size, and resting on a population-level transformation estimate with no data comparing stable and changing cysts, which the guideline admits.",
       "locator": "Gate 9 · Standard option 'Stop at 5 years if stable — AGA 2015, and one of Kyoto 2024's two options'"
      },
      {
       "source": "Kyoto 2024",
       "key": "pm38182527",
       "says": "Offers two options for a small unchanged branch-duct IPMN at 5 years: stop if under 20 mm without worrisome features, weighing life expectancy, or continue for concomitant adenocarcinoma; not for younger or familial-risk patients.",
       "locator": "Gate 9 · Standard option 'Stop at 5 years if stable…'"
      },
      {
       "source": "Marchegiani 2023",
       "key": "pm37406887",
       "says": "After 5 years of stability, standardised incidence ratios of 1.12 at 75 or over and 0.95 at 65 or over with cysts of 15 mm or less underpin the authors' proposal to stop at over 75 with cysts under 30 mm, or at 65 or over with cysts of 15 mm or less; the roadmap notes these rest on 3 and 2 cancers.",
       "locator": "Gate 9 · Standard option 'Stop by age and size — the standardised-incidence-ratio argument'; Practice choices with limited evidence · item 16"
      }
