  "icca": {
   "code": "iCCA",
   "name": "Intrahepatic cholangiocarcinoma",
   "limited": [
    {
     "t": "A solitary iCCA ≤3 cm meets the NLRB size limit; patients with 2–3 cm tumors are told, in consent and in the NLRB narrative, that they are above the size range with the best published outcomes.",
     "why": "Guidance threshold beyond the best data. The 3-cm limit follows NLRB guidance; the strongest outcome data are for single tumors ≤2 cm in a retrospective international series (Sapisochin 2016: 5-year recurrence 18% and survival 65%, n = 15). AASLD/AST statement 11 on small iCCA is a weak recommendation on level 4 evidence. Track recurrence and survival separately for tumors ≤2 cm and 2–3 cm.",
     "setting": "standard",
